//! DataCapability `session.closeSession` (`data-capability.json`): the DM
//! closes the live session in one action. Its microphone stops listening,
//! its close is dated, and a summary of its journal is generated by the
//! summary model of the active provider, then stored on the session with
//! that model's name, for the next preparation to show.
//!
//! The wire payload is empty: the session is the command's target,
//! `Session/<its id>`. [`prepare`] turns it into what the close writes:
//!
//! - a live session is closed — `sessionStatus` closed, `closedAt` now,
//!   `microphoneOn` false — and its journal, the transcribed lines with
//!   their time, is the one text sent to the `llm` port, as a
//!   [`TextKind::Journal`] request: never audio (`text-only-no-audio`);
//! - a session in prep or already closed is refused under
//!   `status-lifecycle` before anything is queued or sent: nothing is
//!   written. A second close of a session whose first is still being
//!   summarised is refused the same way, and one queued behind a first
//!   sees the session closed;
//! - settings that name no provider or no summary model
//!   ([`NO_SUMMARY_PROVIDER`]), or a provider that fails ([`NO_SUMMARY`]),
//!   leave the session closed without a summary, and say so: the
//!   microphone goes off whatever the provider does.
//!
//! The provider is the one the AI settings make active: the `AiSettings/1`
//! row a save left in the engine, else the `ai_settings` row of the tables
//! and the provider it points at, read only. The journal is the
//! `session_journal_line` rows of the session as they are when the close
//! is prepared, their times in the database's time zone, read only: a
//! close never writes them, so they stay on the machine as they were — a
//! line transcribed while the summary is generated included, though the
//! summary does not tell it.
//!
//! The close lands in the tables through [`Closes`], in the transaction
//! that applies it: the `session` row takes it, and every playback of the
//! session still running stops at the close (`stop-all`).

use std::collections::{BTreeMap, BTreeSet};
use std::sync::{Arc, Mutex, PoisonError};

use async_trait::async_trait;
use harness_dataguard::plugins::{self, Context, Plugin, Prepare};
use ports_llm::{
    ApiType, Binary, GenerateRequest, Llm, Models, ProviderConfig, Secret, SharedLlm, TextKind,
};
use serde_json::Value;

mod tables;

pub use tables::Closes;

/// This DataCapability's id, as `data-capability.json` names it.
pub const DATA_CAPABILITY: &str = "session.closeSession";

/// The aggregate it writes, and the prefix of its partitions.
const AGGREGATE: &str = "Session";

/// What a close that stores no summary tells the DM, among its warnings:
/// the provider failed, or answered nothing.
pub const NO_SUMMARY: &str = "résumé non généré : le fournisseur de résumé n'a pas répondu";

/// The same, when the AI settings name no provider the port can reach, or
/// no summary model: nothing was sent.
pub const NO_SUMMARY_PROVIDER: &str =
    "résumé non généré : les paramètres IA ne nomment aucun fournisseur ni modèle de résumé";

/// The session's fields a close reads and writes, as the Session aggregate
/// declares them.
const STATUS: &str = "sessionStatus";
const TITLE: &str = "sessionTitle";
const CLOSED_AT: &str = "closedAt";
const MICROPHONE: &str = "microphoneOn";
const SUMMARY: &str = "summary";
const SUMMARY_MODEL: &str = "summaryModel";

/// The one status a session is closed from, and the one it is closed to.
const LIVE: &str = "live";
const CLOSED: &str = "closed";

/// The settings row a save of the AI settings writes in the engine.
const SETTINGS: &str = "AiSettings/1";

/// The active provider as the tables hold it, named as the settings row
/// names its fields.
const ACTIVE_PROVIDER: &str = r#"SELECT p.mode, p.url, p.detected_api_type AS "detectedApiType",
        p.api_key AS "apiKey", p."binary", p.generation_model AS "generationModel",
        p.summary_model AS "summaryModel"
    FROM ai_settings s JOIN ai_provider p ON p.id = s.active_provider_id
    WHERE s.id = 1"#;

/// The session's journal, in the order it was spoken: each line's time and
/// its text.
const JOURNAL: &str = "SELECT to_char(spoken_at, 'HH24:MI') AS at, text
    FROM session_journal_line WHERE session_id = $1::text::uuid
    ORDER BY spoken_at, id";

/// What the DataCapability plugs into the engine: its `Prepare`, which
/// reaches the `llm` port the server shares, and the close's projection
/// into the tables.
#[must_use]
pub fn plugin() -> Plugin {
    Plugin::new()
        .prepare(DATA_CAPABILITY, CloseSession::default())
        .project_pg(AGGREGATE, Closes)
        .needs::<SharedLlm>()
}

/// Why a close is refused when no `llm` port is shared: the engine refuses
/// to load first, so a server never answers it.
const NO_LLM: &str = "le port llm n'est pas branché";

/// The `Prepare` of `session.closeSession`: [`prepare`], stamped now, on
/// the session the command targets. `closing` holds the sessions whose
/// close is being prepared: the summary takes the provider's time, and a
/// second close of the same session, prepared meanwhile, would see it live.
#[derive(Default)]
struct CloseSession {
    closing: Arc<Mutex<BTreeSet<String>>>,
}

/// A session's close being prepared, until it is dropped.
struct Closing {
    closing: Arc<Mutex<BTreeSet<String>>>,
    id: String,
}

impl CloseSession {
    /// The close of the session `id`, unless one is being prepared.
    fn claim(&self, id: &str) -> Option<Closing> {
        let mut closing = self.closing.lock().unwrap_or_else(PoisonError::into_inner);
        closing.insert(id.to_owned()).then(|| Closing {
            closing: self.closing.clone(),
            id: id.to_owned(),
        })
    }
}

impl Drop for Closing {
    fn drop(&mut self) {
        self.closing
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .remove(&self.id);
    }
}

#[async_trait]
impl Prepare for CloseSession {
    async fn prepare(
        &self,
        context: &Context<'_>,
        _payload: &BTreeMap<String, Value>,
        target_id: Option<&str>,
    ) -> Result<plugins::Prepared, plugins::Refusal> {
        let Some(id) = target_id else {
            return Err(plugins::Refusal::unprocessable(
                "aucune séance : la commande cible la séance à clore",
            ));
        };
        let session = context.row(&format!("{AGGREGATE}/{id}")).await?;
        // Refused before the provider is asked anything.
        closable(&session).map_err(|refusal| refusal.of(id))?;
        let Some(_closing) = self.claim(id) else {
            return Err(Unclosable::Closing.of(id));
        };
        let llm = context
            .shared
            .get::<SharedLlm>()
            .ok_or_else(|| plugins::Refusal::unprocessable(NO_LLM))?;
        let settings = settings(context).await?;
        let journal = journal(context, id).await?;
        let closed_at = timestamp(context.now_millis);
        let Prepared { payload, warning } =
            prepare(llm.as_ref(), &session, &journal, &settings, &closed_at)
                .await
                .map_err(|refusal| refusal.of(id))?;
        Ok(plugins::Prepared {
            payload,
            // The session targeted: the manifest names no payload field
            // that holds it.
            target_id: Some(id.to_owned()),
            warnings: warning.into_iter().map(str::to_owned).collect(),
            ..plugins::Prepared::default()
        })
    }
}

/// The settings that name the active provider: the `AiSettings/1` row a
/// save left, else the tables' active provider; none over the engine's
/// memory before any save.
async fn settings(context: &Context<'_>) -> Result<BTreeMap<String, Value>, plugins::Refusal> {
    let saved = context.row(SETTINGS).await?;
    if saved.contains_key("mode") {
        return Ok(saved);
    }
    let Some(rows) = context.rows else {
        return Ok(saved);
    };
    let found = rows
        .rows(ACTIVE_PROVIDER, &[])
        .await
        .map_err(|e| plugins::Refusal::unprocessable(e.to_string()))?;
    Ok(found
        .get(0)
        .and_then(Value::as_object)
        .map(|row| row.clone().into_iter().collect())
        .unwrap_or_default())
}

/// The journal of the session `id`, as the tables hold it; none over the
/// engine's memory, which has no table.
async fn journal(context: &Context<'_>, id: &str) -> Result<Vec<Line>, plugins::Refusal> {
    let Some(rows) = context.rows.filter(|_| uuid(id)) else {
        return Ok(Vec::new());
    };
    let found = rows
        .rows(JOURNAL, &[Value::from(id)])
        .await
        .map_err(|e| plugins::Refusal::unprocessable(e.to_string()))?;
    Ok(found
        .as_array()
        .into_iter()
        .flatten()
        .map(|line| Line {
            at: line["at"].as_str().unwrap_or_default().to_owned(),
            text: line["text"].as_str().unwrap_or_default().to_owned(),
        })
        .collect())
}

/// One transcribed line of the session's journal: when it was spoken, and
/// what.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Line {
    /// Its time, as the journal shows it.
    pub at: String,
    /// Its text.
    pub text: String,
}

/// What a close becomes before it is submitted.
#[derive(Clone, Debug, PartialEq)]
pub struct Prepared {
    /// The fields written on the session: its status, its close, its
    /// microphone, and — when one was generated — its summary and the
    /// model that wrote it.
    pub payload: BTreeMap<String, Value>,
    /// [`NO_SUMMARY_PROVIDER`] or [`NO_SUMMARY`], when the session is
    /// closed without one.
    pub warning: Option<&'static str>,
}

/// Why a session is not closed: nothing is queued, nothing sent.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Unclosable {
    /// The target names no session the engine or the tables hold.
    Unknown,
    /// The session is not live: in prep, or closed already.
    NotLive(String),
    /// Another close of the session is being prepared.
    Closing,
}

impl Unclosable {
    /// The engine's refusal of the close of the session `id`: 404 for a
    /// session that does not exist, 422 naming `status-lifecycle` for one
    /// that is not live.
    fn of(&self, id: &str) -> plugins::Refusal {
        match self {
            Self::Unknown => plugins::Refusal::not_found(format!("aucune séance {id}")),
            Self::NotLive(status) => plugins::Refusal::unprocessable(format!(
                "status-lifecycle : la séance {id} est « {status} », seule une séance en direct se clôt"
            )),
            Self::Closing => plugins::Refusal::unprocessable(format!(
                "status-lifecycle : la séance {id} est déjà en train d'être close"
            )),
        }
    }
}

/// Whether `session` — its row as the commands queued on it will leave it
/// — can be closed: it exists, and it is live.
///
/// # Errors
///
/// [`Unclosable::Unknown`] when the row holds no status,
/// [`Unclosable::NotLive`] when it is in prep or closed.
pub fn closable(session: &BTreeMap<String, Value>) -> Result<(), Unclosable> {
    match session.get(STATUS).and_then(Value::as_str) {
        None => Err(Unclosable::Unknown),
        Some(LIVE) => Ok(()),
        Some(status) => Err(Unclosable::NotLive(status.to_owned())),
    }
}

/// The provider `settings` makes active — the AiSettings row as the engine
/// or the tables hold it: `mode`, `url`, `detectedApiType`, `apiKey`,
/// `binary`, `generationModel`, `summaryModel` — or `None` when it names no
/// provider the port can reach, or no summary model.
#[must_use]
pub fn provider(settings: &BTreeMap<String, Value>) -> Option<ProviderConfig> {
    let models = Models {
        generation: text(settings, "generationModel").to_owned(),
        summary: text(settings, SUMMARY_MODEL).to_owned(),
    };
    if models.summary.trim().is_empty() {
        return None;
    }
    match text(settings, "mode") {
        "api" => {
            let url = text(settings, "url");
            let api_type = match text(settings, "detectedApiType") {
                "cloud" => Some(ApiType::Cloud),
                "opencode" => Some(ApiType::Opencode),
                _ => None,
            };
            let key = Some(text(settings, "apiKey")).filter(|key| !key.is_empty());
            (!url.is_empty()).then(|| ProviderConfig::Api {
                url: url.to_owned(),
                api_type,
                key: key.map(Secret::new),
                models,
            })
        }
        "binaire" | "binary" => {
            let binary = match text(settings, "binary") {
                "claude-code" | "claude" => Some(Binary::ClaudeCode),
                "opencode" => Some(Binary::Opencode),
                _ => None,
            };
            binary.map(|binary| ProviderConfig::Binary { binary, models })
        }
        _ => None,
    }
}

/// The text a summary is asked of: the session's title, then each journal
/// line with its time, in order. Text only: the lines as transcribed.
#[must_use]
pub fn journal_text(session: &BTreeMap<String, Value>, journal: &[Line]) -> String {
    let mut sent = format!("Journal de la séance « {} »", text(session, TITLE));
    if journal.is_empty() {
        sent.push_str("\n(aucune ligne transcrite)");
    }
    for line in journal {
        sent.push('\n');
        sent.push_str(&line.at);
        sent.push(' ');
        sent.push_str(&line.text);
    }
    sent
}

/// Prepares the close of `session` — its row as the commands queued on it
/// will leave it — at `closed_at` (RFC 3339): its `journal` is summarised
/// through `llm` by the summary model `settings` names.
///
/// # Errors
///
/// [`Unclosable`] when `session` does not exist or is not live
/// ([`closable`]): nothing reaches the provider.
pub async fn prepare<L: Llm>(
    llm: &L,
    session: &BTreeMap<String, Value>,
    journal: &[Line],
    settings: &BTreeMap<String, Value>,
    closed_at: &str,
) -> Result<Prepared, Unclosable> {
    closable(session)?;
    let mut payload: BTreeMap<String, Value> = [
        (STATUS, Value::from(CLOSED)),
        (CLOSED_AT, closed_at.into()),
        (MICROPHONE, false.into()),
    ]
    .into_iter()
    .map(|(field, value)| (field.to_owned(), value))
    .collect();
    let unsummarised = |warning| Prepared {
        payload: payload.clone(),
        warning: Some(warning),
    };
    let Some(config) = provider(settings) else {
        return Ok(unsummarised(NO_SUMMARY_PROVIDER));
    };
    let request = GenerateRequest::new(TextKind::Journal, journal_text(session, journal));
    let answer = llm
        .generate(&config, &request)
        .await
        .ok()
        .filter(|answer| !answer.text.trim().is_empty());
    let Some(answer) = answer else {
        return Ok(unsummarised(NO_SUMMARY));
    };
    // The model the settings name, as the DM configured it: the one the
    // next preparation shows.
    let model = config.models().summary.clone();
    payload.insert(SUMMARY.to_owned(), answer.text.into());
    payload.insert(SUMMARY_MODEL.to_owned(), model.into());
    Ok(Prepared {
        payload,
        warning: None,
    })
}

/// Whether `id` is a uuid, written 8-4-4-4-12 in hex digits: the ids the
/// tables key a session by.
fn uuid(id: &str) -> bool {
    id.len() == 36
        && id.char_indices().all(|(i, c)| match i {
            8 | 13 | 18 | 23 => c == '-',
            _ => c.is_ascii_hexdigit(),
        })
}

/// A field as text; empty when absent, `null` or not a string.
fn text<'a>(row: &'a BTreeMap<String, Value>, field: &str) -> &'a str {
    row.get(field).and_then(Value::as_str).unwrap_or_default()
}

/// `unix_millis` as RFC 3339 in UTC, to the millisecond
/// (`2026-10-17T10:00:00.123Z`): how the close is dated.
#[must_use]
pub fn timestamp(unix_millis: u64) -> String {
    let seconds = unix_millis / 1000;
    // Howard Hinnant's civil_from_days: the days since the epoch, a u64
    // divided by 86 400, always fit an i64.
    let days = (seconds / 86_400).cast_signed() + 719_468;
    let era = days.div_euclid(146_097);
    let doe = days.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = yoe + era * 400 + i64::from(month <= 2);
    let time = seconds % 86_400;
    format!(
        "{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}.{:03}Z",
        time / 3600,
        time % 3600 / 60,
        time % 60,
        unix_millis % 1000
    )
}
